def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict[chain[0]]
    result = []

    while current:
        result.append(current.pop())
        next_token = current[-1]
        if next_token not in chain_dict:
            chain_dict[next_token] = []
        current = chain_dict[next_token]

    return ','.join(result)
```

